select report_no reportNo, complete_time completeTime, count(distinct product_seq) productCategoryTotalNum, sum(complete_num) productTotalNum, source_channel sourceChannel, complete_user completeUser from micro_complete_report
and source_channel =#{sourceChannel}
and complete_time >= #{startDate}
and complete_time <= #{endDate}
and `state` in ('0', '2')
group by report_no order by complete_time desc

select a.product_seq productSeq, b.product_code productCode, a.product_name productName, sum(a.complete_num) completeTotalNum from micro_complete_report a left join micro_product b on a.product_seq = b.product_seq
and a.source_channel =#{sourceChannel}
and a.complete_time >= #{startDate}
and a.complete_time <= #{endDate}
and (b.product_code like concat('%', #{productCodeOrName}, '%') or b.product_name like concat('%', #{productCodeOrName}, '%'))
and a.`state` in ('0', '2')
group by a.product_seq

select a.id workOrderId, a.work_order_no workOrderNo, a.order_no orderNo, a.product_seq productSeq, a.wshop_code wshopCode, a.mline_code mlineCode, a.plan_start_date planStartDate, a.plan_end_date planEndDate, a.produce_start_date produceStartDate, a.produce_end_date produceEndDate, b.complete_num completeNum, b.complete_time completeTime, b.complete_user completeUser, b.id completeReportId from micro_manufacture_work_order a left join micro_complete_report b on a.id = b.work_submit_id
and a.active_flag = '1' and b.`state` in ('0', '2')
and b.source_channel =#{sourceChannel}
and b.complete_time >= #{startDate}
and b.complete_time <= #{endDate}
and (a.work_order_no like concat('%', #{orderOrWorkNo}, '%') or a.order_no like concat('%', #{orderOrWorkNo}, '%'))
order by b.complete_time desc




